<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {request,isCancelled} from '../../shared/api/client'
import type {AssistantStatus} from '../../shared/interfaces/assistant'
import {authLabel} from '../../shared/interfaces/assistant'
import Icon from '../../shared/ui/Icon.vue'
const emit=defineEmits<{status:[AssistantStatus];close:[]}>(),status=ref<AssistantStatus|null>(null),key=ref(''),error=ref(''),busy=ref(false),now=ref(Date.now()),controller=new AbortController()
let revision=0,timer:ReturnType<typeof setTimeout>|undefined;const clock=setInterval(()=>{now.value=Date.now()},1000)
const pending=computed(()=>status.value?.pending_login),expired=computed(()=>!!pending.value&&Date.parse(pending.value.expires_at)<=now.value),minutes=computed(()=>pending.value?Math.max(0,Math.ceil((Date.parse(pending.value.expires_at)-now.value)/60000)):0)
const verificationUrl=computed(()=>{try{const u=new URL(pending.value?.verification_url||'');return u.protocol==='https:'&&u.hostname==='auth.openai.com'&&u.pathname==='/codex/device'&&!u.username&&!u.password&&!u.hash?u.href:''}catch{return''}})
function adopt(value:AssistantStatus){status.value=value;emit('status',{...value,pending_login:null});clearTimeout(timer);if(value.pending_login&&Date.parse(value.pending_login.expires_at)>Date.now()&&!controller.signal.aborted)timer=setTimeout(load,2000)}
async function load(){const captured=revision;try{const result=await request<AssistantStatus>('/assistant/status',{signal:controller.signal});if(captured!==revision)return;adopt(result);error.value=''}catch(e){if(!isCancelled(e)&&captured===revision)error.value='Не удалось проверить подключение модели.'}}
async function authenticate(type:'apiKey'|'chatgptDeviceCode'){if(busy.value||type==='apiKey'&&!key.value.trim())return;revision++;busy.value=true;error.value='';clearTimeout(timer);try{adopt(await request<AssistantStatus>('/assistant/auth/start',{method:'POST',body:type==='apiKey'?{type,api_key:key.value.trim()}:{type},signal:controller.signal}));if(!status.value?.authenticated&&!status.value?.pending_login)error.value='Подключение не подтверждено. Проверьте доступность модели.'}catch(e){if(!isCancelled(e))error.value='Не удалось начать вход. Проверьте доступность сервиса и выбранный способ авторизации.'}finally{key.value='';busy.value=false}}
async function cancel(){if(!pending.value||busy.value)return;revision++;clearTimeout(timer);busy.value=true;try{adopt(await request<AssistantStatus>('/assistant/auth/cancel',{method:'POST',body:{login_id:pending.value.login_id},signal:controller.signal}))}catch(e){if(!isCancelled(e))error.value='Не удалось подтвердить отмену входа. Обновите статус.'}finally{busy.value=false}}
async function logout(){if(busy.value)return;revision++;clearTimeout(timer);busy.value=true;try{adopt(await request<AssistantStatus>('/assistant/auth/logout',{method:'POST',body:{},signal:controller.signal}))}catch(e){if(!isCancelled(e))error.value='Не удалось отключить модель. Повторите проверку.'}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(pending.value?.user_code||'')}catch{error.value='Код можно выделить и скопировать вручную.'}}
onMounted(load);onUnmounted(()=>{controller.abort();clearTimeout(timer);clearInterval(clock);key.value='';status.value=null})
</script>
<template><section class="assistant-model" aria-label="Подключение Codex"><div class="assistant-secure-heading"><span><Icon name="activity" :size="17"/>Модель помощника</span><button class="icon-button" aria-label="Закрыть подключение модели" @click="emit('close')"><Icon name="close" :size="16"/></button></div><p class="assistant-model-status" role="status">{{authLabel(status)}}</p><p>Доступ к Codex настраивается для текущей компании. История диалогов остаётся личной.</p><p v-if="status?.codex_version" class="subtle">Codex {{status.codex_version}}<span v-if="status.model"> · {{status.model}}</span></p><p v-if="status&&(!status.available||!status.runner_ready)" class="assistant-error">Сервис недоступен. Запуск Docker-контейнера не подтверждает доступ к модели.</p><template v-if="status?.authenticated"><span class="badge teal"><Icon name="check" :size="13"/>Вход подтверждён{{status.auth_mode==='chatgpt'?' · аккаунт':' · API-ключ'}}</span><button class="button small" :disabled="busy" @click="logout" style="margin-top:12px">Отключить Codex</button></template><template v-else><div v-if="pending" class="assistant-device"><template v-if="!expired"><p>Откройте страницу входа и введите код:</p><div class="assistant-device-code"><code>{{pending.user_code}}</code><button class="button small" @click="copy">Копировать</button></div><a v-if="verificationUrl" :href="verificationUrl" target="_blank" rel="noopener noreferrer" class="button primary small">Открыть страницу входа</a><p v-else class="assistant-error">Сервер вернул неподдерживаемый адрес входа.</p><small>Код действителен ещё {{minutes}} мин. Ожидаем подтверждения входа.</small></template><p v-else class="assistant-error">Срок кода истёк. Начните вход заново.</p><button class="text-link" :disabled="busy" @click="cancel">Отменить вход</button></div><button class="button small full" :disabled="busy||!status?.runner_ready||!!pending&&!expired" @click="authenticate('chatgptDeviceCode')">{{busy?'Подключаем…':'Войти через аккаунт ChatGPT'}}</button><div class="assistant-divider-label">или API-ключ</div><form autocomplete="off" @submit.prevent="authenticate('apiKey')"><label>API-ключ Codex<input v-model="key" type="password" autocomplete="new-password" placeholder="Ключ не попадёт в переписку" :disabled="busy" required/></label><button class="button primary small full" style="margin-top:12px" :disabled="busy||!key.trim()||!status?.runner_ready">Подключить по ключу</button></form></template><p v-if="error" class="assistant-error" role="alert">{{error}}</p><button class="text-link" style="margin-top:12px" :disabled="busy" @click="load">Проверить подключение</button></section></template>
